const {deepStrictEqual} = require('node:assert').strict;
const test = require('node:test');

const {resolutionType} = require('./../../resolutions');

// HTLC resolution transaction test vectors from BOLT 03 appendices
//
// Appendix C transactions are from "commitment tx with all five HTLCs
// untrimmed (minimum feerate)"
// Appendix F transactions are the HTLC resolution transactions of
// "commitment tx with seven outputs untrimmed"

const tests = [
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix C htlc_timeout_tx for HTLC 2 is an offered HTLC timeout',
    expected: {type: 'offered_htlc_timeout'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix C htlc_success_tx for HTLC 0 is a received HTLC settle',
    expected: {type: 'received_htlc_settled'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix F success resolution of HTLC 0 is a received HTLC settle',
    expected: {type: 'received_htlc_settled'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix F timeout resolution of HTLC 2 is an offered HTLC timeout',
    expected: {type: 'offered_htlc_timeout'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix F success resolution of HTLC 1 is a received HTLC settle',
    expected: {type: 'received_htlc_settled'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix F timeout resolution of HTLC 3 is an offered HTLC timeout',
    expected: {type: 'offered_htlc_timeout'},
  },
  {
    args: {
      transaction: '',
      vin: 0,
    },
    description: 'Appendix F success resolution of HTLC 4 is a received HTLC settle',
    expected: {type: 'received_htlc_settled'},
  },
];

tests.forEach(({args, description, expected}) => {
  return test(description, (t, end) => {
    const {type} = resolutionType(args);

    deepStrictEqual(type, expected.type, 'Type is resolved');

    return end();
  });
});
